+	}
+	bodyKey := DeriveSessionSubKey(psk, sidBuf[:], method.KeySaltLength)
+	s.serverBodyCipher, err = method.NewAEAD(bodyKey)
+	if err != nil {
+		s.ServerSessionID = 0
+		return err
+	}
+	return nil
+}
