+// ServerStreamWriter lazily sends the response header along with the first payload chunk per SIP022 §3.1.2 & §3.1.4.
+type ServerStreamWriter struct {
+	mu           sync.Mutex
+	w            io.Writer
+	method       *CipherMethod
+	psk          []byte
+	clientSalt   []byte
+	streamWriter *StreamWriter
+}
