+			rules:       []*router.RoutingRule{port53Rule()},
+			wantErr:     "",
+		},
+		{
+			name:    "no dns section falls back to the system resolver",
+			rules:   []*router.RoutingRule{port53Rule()},
+			wantErr: "system resolver",
+		},
+		{
